    id: 106,
    lottie: "fee.lottie",
    fallback: "💼",
    accent: "#3fae6b",
    en: { bubble: "The bank does this for you — for a fee.", narration: "So who actually runs all this? The bank. It does the reclaim on behalf of the investor and charges for it. The fee is usually structured two ways: a volume-based fee with a minimum, so small cases still pay something; plus a success fee — a slice of the money — paid only when the refund actually comes back. That combination is exactly why reclaim and relief-at-source are the most lucrative products in this space: the bank earns on volume and again on success, on thousands of cases at scale.", flow: { nodes: [ {icon:"💰",label:"Refund"}, {icon:"🏦",label:"Bank"}, {icon:"✂️",label:"volume fee + min",tone:"bad"}, {icon:"✂️",label:"success fee",tone:"bad"}, {icon:"🧑‍💼",label:"Investor paid out",tone:"good"} ] } },
    pt: { bubble: "O banco faz isso por você — por uma fee.", narration: "Então quem roda tudo isso? O banco. Ele faz o reclaim em nome do investidor e cobra por isso. A fee geralmente vem em duas partes: uma fee por volume com um mínimo, pra que casos pequenos ainda paguem algo; mais uma success fee — uma fatia do dinheiro — paga só quando o reembolso volta de fato. Essa combinação é justamente por que reclaim e relief-at-source são os produtos mais lucrativos desse mercado: o banco ganha no volume e de novo no sucesso, em milhares de casos em escala.", flow: { nodes: [ {icon:"💰",label:"Reembolso"}, {icon:"🏦",label:"Banco"}, {icon:"✂️",label:"fee volume + mín.",tone:"bad"}, {icon:"✂️",label:"success fee",tone:"bad"}, {icon:"🧑‍💼",label:"Investidor recebe",tone:"good"} ] } },
